async def prepare_shipment_sources(
    session: AsyncSession,
    *,
    tenant_id: uuid.UUID,
    warehouse_id: uuid.UUID,
    orders: list[FbsOrder],
) -> list[FbsShipmentReversalLedger]:
    """Save the existing per-order reversal recipe before any external handoff."""
    orders = [order for order in orders if order.status != FBS_ORDER_STATUS_CANCELLED]
    ledgers = {
        ledger.fbs_order_id: ledger
        for ledger in (
            await session.scalars(
                select(FbsShipmentReversalLedger)
                .where(
                    FbsShipmentReversalLedger.tenant_id == tenant_id,
                    FbsShipmentReversalLedger.fbs_order_id.in_([order.id for order in orders]),
                )
                .with_for_update()
            )
        ).all()
    }
    recipes: dict[uuid.UUID, list[dict[str, Any]]] = {}
    requests: list[source_svc.FbsShipmentSourceRequest] = []
    consumption: dict[tuple[uuid.UUID, uuid.UUID, ContainerKind | None, uuid.UUID | None], int] = {}
    for order in orders:
        ledger = ledgers.get(order.id)
        if ledger is not None:
            if ledger.reversed_at is not None:
                raise OzonPackagingError("fbs_shipment_already_reversed")
            if ledger.shipment_movement_id is not None:
                continue
        positions = order.product_positions
        if positions and any(position.product_id is None for position in positions):
            raise OzonPackagingError("fbs_shipment_product_missing")
        expected: Counter[uuid.UUID] = Counter()
        for position in positions:
            if position.quantity <= 0:
                raise OzonPackagingError("fbs_shipment_source_missing")
            if position.product_id is not None:
                expected[position.product_id] += int(position.quantity)
        if not positions and order.product_id is not None:
            expected[order.product_id] = 1
        if not expected:
            raise OzonPackagingError("fbs_shipment_product_missing")
        if ledger is not None and ledger.ozon_positions_json:
            staged: Counter[uuid.UUID] = Counter()
            for staged_row in ledger.ozon_positions_json:
                staged[uuid.UUID(str(staged_row["product_id"]))] += int(str(staged_row["quantity"]))
            if staged == expected:
                recipes[order.id] = list(ledger.ozon_positions_json)
                continue
            # An earlier attempt may have stopped before assembly. Its source
            # recipe must not retain an older quantity after a real composition change.
            ledger.ozon_positions_json = None
        fulfillment = await active_order_fulfillment(session, order.id)
        units = packed_units(fulfillment)
        grouped: dict[tuple[uuid.UUID, uuid.UUID], int] = defaultdict(int)
        try:
            for unit in units:
                grouped[
                    (uuid.UUID(unit["product_id"]), uuid.UUID(unit["storage_location_id"]))
                ] += 1
        except (KeyError, ValueError) as exc:
            raise OzonPackagingError("invalid_ozon_packaging_fulfillment") from exc
        packed: Counter[uuid.UUID] = Counter()
        for (product_id, _), quantity in grouped.items():
            packed[product_id] += quantity
        if units and packed == expected:
            recipes[order.id] = [
                {
                    "product_id": str(product_id),
                    "storage_location_id": str(location_id),
                    "quantity": quantity,
                }
                for (product_id, location_id), quantity in grouped.items()
            ]
        else:
            # Unit requests allow the existing planner to span several stock keys
            # for a single position, without silently discarding repeated order IDs.
            requests.extend(
                source_svc.FbsShipmentSourceRequest(
                    fbs_order_id=order.id,
                    product_id=product_id,
                    quantity=1,
                )
                for product_id, quantity in expected.items()
                for _ in range(quantity)
            )
    for recipe in recipes.values():
        for row in recipe:
            consumption_key = (
                uuid.UUID(str(row["product_id"])),
                uuid.UUID(str(row["storage_location_id"])),
                cast(ContainerKind | None, row.get("container_kind")),
                uuid.UUID(str(row["container_id"])) if row.get("container_id") else None,
            )
            consumption[consumption_key] = consumption.get(consumption_key, 0) + int(
                row["quantity"]
            )
    plan = await source_svc.plan_fbs_shipment_sources(
        session,
        tenant_id=tenant_id,
        supply_warehouse_id=warehouse_id,
        requests=requests,
        initial_consumption=consumption,
    )
    grouped_resolutions: dict[
        tuple[uuid.UUID, uuid.UUID, uuid.UUID, str | None, uuid.UUID | None], dict[str, Any]
    ] = {}
    for resolution in plan.resolutions:
        key = (
            resolution.fbs_order_id,
            resolution.product_id,
            resolution.storage_location_id,
            resolution.container_kind,
            resolution.container_id,
        )
        row = grouped_resolutions.setdefault(
            key,
            {
                "product_id": str(resolution.product_id),
                "storage_location_id": str(resolution.storage_location_id),
                "source_warehouse_id": str(resolution.source_warehouse_id),
                "container_kind": resolution.container_kind,
                "container_id": str(resolution.container_id) if resolution.container_id else None,
                "source_mode": resolution.source_mode,
                "quantity": 0,
                "negative_quantity": 0,
            },
        )
        row["quantity"] += resolution.quantity
        row["negative_quantity"] += resolution.negative_quantity
    for recipe_key, row in grouped_resolutions.items():
        recipes.setdefault(recipe_key[0], []).append(row)
    for order_id, recipe in recipes.items():
        ledger = ledgers.get(order_id)
        if ledger is None:
            first = recipe[0]
            ledger = FbsShipmentReversalLedger(
                tenant_id=tenant_id,
                fbs_order_id=order_id,
                product_id=uuid.UUID(str(first["product_id"])),
                storage_location_id=uuid.UUID(str(first["storage_location_id"])),
                source_warehouse_id=warehouse_id,
                quantity=sum(int(row["quantity"]) for row in recipe),
                ozon_positions_json=recipe,
                negative_quantity=sum(int(row.get("negative_quantity", 0)) for row in recipe),
                shortage_quantity=sum(int(row.get("negative_quantity", 0)) for row in recipe),
            )
            session.add(ledger)
            ledgers[order_id] = ledger
        elif not ledger.ozon_positions_json:
            first = recipe[0]
            ledger.product_id = uuid.UUID(str(first["product_id"]))
            ledger.storage_location_id = uuid.UUID(str(first["storage_location_id"]))
            ledger.quantity = sum(int(row["quantity"]) for row in recipe)
            ledger.negative_quantity = sum(int(row.get("negative_quantity", 0)) for row in recipe)
            ledger.shortage_quantity = ledger.negative_quantity
            ledger.ozon_positions_json = recipe
    await session.flush()
    return list(ledgers.values())


async def write_off_order(
    session: AsyncSession,
    *,
    tenant_id: uuid.UUID,
    order: FbsOrder,
    actor_user_id: uuid.UUID | None,
    ledger: FbsShipmentReversalLedger | None = None,
) -> FbsShipmentReversalLedger:
    """Apply the saved source recipe only after confirmed marketplace handoff."""
    if ledger is None:
        if order.warehouse_id is None:
            raise OzonPackagingError("fbs_shipment_source_missing")
        prepared = await prepare_shipment_sources(
            session,
            tenant_id=tenant_id,
            warehouse_id=order.warehouse_id,
            orders=[order],
        )
        ledger = prepared[0]
    if ledger.shipment_movement_id is not None:
        return ledger
    if not ledger.ozon_positions_json:
        raise OzonPackagingError("fbs_shipment_source_missing")
    for row in ledger.ozon_positions_json:
        quantity = int(str(row["quantity"]))
        allow_negative = int(str(row.get("negative_quantity", 0))) > 0
        values: dict[str, Any] = {
            "fbs_order_id": order.id,
            "tenant_id": tenant_id,
            "product_id": uuid.UUID(str(row["product_id"])),
            "storage_location_id": uuid.UUID(str(row["storage_location_id"])),
            "quantity": quantity,
            "actor_user_id": actor_user_id,
            "container_kind": cast(ContainerKind | None, row.get("container_kind")),
            "container_id": uuid.UUID(str(row["container_id"]))
            if row.get("container_id")
            else None,
        }
        try:
            async with session.begin_nested():
                movement = await inv_svc.apply_fbs_supply_write_off(
                    session,
                    **values,
                    allow_negative=allow_negative,
                )
        except ValueError as exc:
            if allow_negative or str(exc) != "insufficient stock":
                raise
            # Same policy as WB: external handoff is already confirmed. Record
            # the actual shortage instead of losing the local half of delivery.
            movement = await inv_svc.apply_fbs_supply_write_off(
                session,
                **values,
                allow_negative=True,
            )
            ledger.negative_quantity += quantity
            ledger.shortage_quantity += quantity
        await session.flush()
        if ledger.shipment_movement_id is None:
            ledger.shipment_movement_id = movement.id
    await session.flush()
    return ledger

def storage_day_source_id(*, warehouse_id: uuid.UUID, product_id: uuid.UUID) -> uuid.UUID:
    """Адрес строки начисления. Публичный: по нему экран хранения находит
    начисленное за товар, вместо того чтобы считать хранение второй раз."""
    return uuid.uuid5(SOURCE_NAMESPACE, f"{warehouse_id}:{product_id}")


def storage_day_event_kind(day: date) -> str:
    """Ключ суток начисления — им же экран отбирает нужный месяц."""
    return f"storage_day:{day.isoformat()}"


def storage_day_topup_event_kind(day: date, index: int) -> str:
    """Ключ доначисления за те же сутки.

    Начисление, уже уехавшее в выставленный счёт, переписывать нельзя: счёт
    помнит свою сумму, а строку считает израсходованной и второй раз в счёт не
    берёт — разницу не выставят никогда. Поэтому недостающее пишем соседней
    строкой за те же сутки, и уникальность «услуга + событие» держит её отдельно.
    """
    return f"{storage_day_event_kind(day)}:topup{index}"


def previous_moscow_day(now: datetime | None = None) -> date:
    """Прошедшие сутки для запуска в 00:00 по Москве."""
    moment = (now or datetime.now(MOSCOW)).astimezone(MOSCOW)
    return moment.date() - timedelta(days=1)


def _day_bounds(day: date) -> tuple[datetime, datetime]:
    start = datetime.combine(day, time.min, MOSCOW)
    return start, start + timedelta(days=1)


async def charge_storage_day(
    session: AsyncSession,
    tenant_id: uuid.UUID,
    *,
    day: date,
) -> int:
    """Начислить хранение арендатора за одни сутки. Повтор безопасен.

    Возвращает количество созданных строк начисления.
    """
    billing_enabled_from = await session.scalar(
        select(Tenant.billing_enabled_from).where(Tenant.id == tenant_id)
    )
    if billing_enabled_from is None or day < billing_enabled_from:
        # Пока у арендатора не проставлена дата начала биллинга, работа склада
        # не стоит денег — так же, как и у операционных начислений.
        return 0

    start, end = _day_bounds(day)
    warehouse_ids = set(
        (
            await session.scalars(
                select(Warehouse.id).where(
                    Warehouse.tenant_id == tenant_id,
                    Warehouse.is_operational.is_(True),
                )
            )
        ).all()
    )
    if not warehouse_ids:
        return 0

    # Литро-дни считаются по всей истории движений до конца суток: остаток на
    # начало дня восстанавливается из неё, отдельного среза остатков нет.
    movements = list(
        (
            await session.scalars(
                select(InventoryMovement)
                .where(
                    InventoryMovement.tenant_id == tenant_id,
                    InventoryMovement.warehouse_id.in_(warehouse_ids),
                    InventoryMovement.created_at < end,
                )
                .order_by(InventoryMovement.created_at, InventoryMovement.id)
            )
        ).all()
    )
    if not movements:
        return 0

    product_ids = {movement.product_id for movement in movements}
    products = {
        product.id: product
        for product in (
            await session.scalars(select(Product).where(Product.id.in_(product_ids)))
        ).all()
    }
    events_by_product: dict[uuid.UUID, list[ProductDimensionEvent]] = {}
    for event in (
        await session.scalars(
            select(ProductDimensionEvent)
            .where(
                ProductDimensionEvent.tenant_id == tenant_id,
                ProductDimensionEvent.product_id.in_(product_ids),
            )
            .order_by(ProductDimensionEvent.observed_at, ProductDimensionEvent.id)
        )
    ).all():
        events_by_product.setdefault(event.product_id, []).append(event)

    grouped: dict[tuple[uuid.UUID, uuid.UUID, uuid.UUID], list[InventoryMovement]] = {}
    for movement in movements:
        if movement.seller_id is None or movement.warehouse_id is None:
            continue
        if movement.product_id not in products:
            continue
        grouped.setdefault(
            (movement.seller_id, movement.warehouse_id, movement.product_id), []
        ).append(movement)
    if not grouped:
        return 0

    # Берём сами строки, а не только их адреса: сутки могли быть посчитаны
    # частично — товар часть дня лежал без известного объёма. Тогда строка есть,
    # но она меньше правды, и её надо дописать, а не пропустить навсегда.

async def update_fbs_order_reservation(
    session: AsyncSession,
    order: FbsOrder,
    *,
    reserve: bool,
) -> None:
    """Общая операция WB/Ozon: доступность ↔ существующий резерв заказа.

    Физическое списание остаётся в record_movement_and_adjust_balance. После
    проведённого списания снятие резерва не возвращает доступность.
    """
    from app.services.fbs_stock_availability_service import fbs_available_qty_for_product

    positions = list(
        (
            await session.scalars(
                select(FbsOrderProduct)
                .where(FbsOrderProduct.order_id == order.id)
                .order_by(FbsOrderProduct.id)
            )
        ).all()
    )
    required: dict[uuid.UUID, int] = {}
    if order.marketplace == "ozon" and positions:
        for position in positions:
            if position.product_id is None or position.quantity < 1:
                if reserve:
                    order.reserve_status = RESERVE_STATUS_SKIPPED_NO_PRODUCT
                    return
                continue
            required[position.product_id] = required.get(position.product_id, 0) + position.quantity
    elif order.product_id is not None:
        required[order.product_id] = 1
    elif reserve:
        order.reserve_status = RESERVE_STATUS_SKIPPED_NO_PRODUCT
        return
    # Include old reservation products even if mapping/composition has changed.
    existing = list(
        (
            await session.scalars(
                select(FbsOrderReservation).where(FbsOrderReservation.fbs_order_id == order.id)
            )
        ).all()
    )
    position_reserves = list(
        (
            await session.scalars(
                select(FbsOrderProductReservation)
                .join(FbsOrderProduct)
                .where(FbsOrderProduct.order_id == order.id)
            )
        ).all()
    )
    reservations: list[FbsOrderReservation | FbsOrderProductReservation] = [
        *existing,
        *position_reserves,
    ]
    product_ids = set(required) | {r.product_id for r in reservations}
    products = {
        pid: await lock_stock_product(session, order.tenant_id, pid)
        for pid in sorted(product_ids, key=str)
    }
    # Re-read AFTER the lock: concurrent import/cancellation may have committed.
    existing = list(
        (
            await session.scalars(
                select(FbsOrderReservation)
                .where(FbsOrderReservation.fbs_order_id == order.id)
                .execution_options(populate_existing=True)
            )
        ).all()
    )
    position_reserves = list(
        (
            await session.scalars(
                select(FbsOrderProductReservation)
                .join(FbsOrderProduct)
                .where(FbsOrderProduct.order_id == order.id)
                .execution_options(populate_existing=True)
            )
        ).all()
    )
    reservations = [*existing, *position_reserves]
    shipped = (
        await session.scalar(
            select(FbsShipmentReversalLedger.id).where(
                FbsShipmentReversalLedger.fbs_order_id == order.id,
                FbsShipmentReversalLedger.shipment_movement_id.is_not(None),
            )
        )
        is not None
    )
    if reserve:
        if reservations or shipped:
            return
        if order.warehouse_id is None:
            order.reserve_status = RESERVE_STATUS_WAREHOUSE_UNMAPPED
            return
        pools: dict[uuid.UUID, FbsBindingStockPool] = {}
        for pid, quantity in required.items():
            product = products[pid]
            if product is None:
                order.reserve_status = RESERVE_STATUS_SKIPPED_NO_PRODUCT
                return
            if product.fbs_units_mode:
                pool = await _order_stock_pool(session, order, pid)
                if pool is None or pool.quantity < quantity:
                    order.reserve_status = RESERVE_STATUS_NO_STOCK
                    return
                pools[pid] = pool
            else:
                if order.marketplace == "wb" and (
                    not product.fbs_stock_sync_enabled or product.fbs_percent is None
                ):
                    order.reserve_status = RESERVE_STATUS_NOT_PUBLISHED
                    return
                available = await fbs_available_qty_for_product(
                    session,
                    order.tenant_id,
                    order.warehouse_id,
                    pid,
                    exclude_fbs_order_id=order.id,
                )
                if available < quantity:
                    order.reserve_status = RESERVE_STATUS_NO_STOCK
                    return
        for pid, pool in pools.items():
            pool.quantity -= required[pid]
        if order.marketplace == "ozon" and positions:
            for position in positions:
                assert position.product_id is not None
                session.add(
                    FbsOrderProductReservation(
                        tenant_id=order.tenant_id,
                        order_product_id=position.id,
                        product_id=position.product_id,
                        warehouse_id=order.warehouse_id,
                        quantity=position.quantity,
                    )
                )
                position.reserved_quantity = position.quantity
        else:
            assert order.product_id is not None
            session.add(
                FbsOrderReservation(
                    tenant_id=order.tenant_id,
                    fbs_order_id=order.id,
                    product_id=order.product_id,
                    warehouse_id=order.warehouse_id,
                    quantity=1,
                )
            )
        order.reserve_status = RESERVE_STATUS_RESERVED
    else:
        if not reservations:
            return
        for reservation in reservations:
            product = products[reservation.product_id]
            if not shipped and product is not None and product.fbs_units_mode:
                pool = await _order_stock_pool(session, order, reservation.product_id)
                if pool is not None:
                    pool.quantity += reservation.quantity
            await session.delete(reservation)
        for position in positions:
            position.reserved_quantity = 0
        order.reserve_status = RESERVE_STATUS_RELEASED
    await session.flush()
    schedule_seller_stock_publish(session, order.tenant_id, order.seller_id)


